<script setup>
import {ref,onMounted} from 'vue';import AppShell from '../components/AppShell.vue';import {supabase} from '../services/supabase';import {RouterLink} from 'vue-router';const jobs=ref([]),loading=ref(true),error=ref('');async function load(){const {data:{user}}=await supabase.auth.getUser();const {data,error:e}=await supabase.from('jobs').select('*').eq('employer_id',user.id).order('created_at',{ascending:false});jobs.value=data||[];error.value=e?.message||'';loading.value=false}onMounted(load);async function setStatus(job,status){const {error:e}=await supabase.from('jobs').update({status}).eq('id',job.id);if(e)error.value=e.message;else job.status=status}async function remove(job){if(!confirm(`Remove “${job.title}” from active opportunities?`))return;const {count}=await supabase.from('applications').select('*',{count:'exact',head:true}).eq('job_id',job.id);if((count||0)>0){const {error:e}=await supabase.from('jobs').update({status:'closed'}).eq('id',job.id);if(e)error.value=e.message;else job.status='closed'}else{const {error:e}=await supabase.from('jobs').delete().eq('id',job.id);if(e)error.value=e.message;else jobs.value=jobs.value.filter(x=>x.id!==job.id)}}
</script>
<template><AppShell title="My job posts" subtitle="Manage your opportunities"><template #default><div class="page-heading"><div><span class="eyebrow">EMPLOYER WORKSPACE</span><h1 class="page-title">Your job posts</h1><p class="page-subtitle">Keep your job posts current and review incoming applications.</p></div><RouterLink to="/post-job" class="btn btn-primary">＋ Post a job</RouterLink></div><div v-if="error" class="alert error">{{error}}</div><div v-if="loading" class="empty">Loading job posts…</div><div v-else-if="jobs.length" class="table-wrap" style="margin-top:22px"><table><thead><tr><th>Job</th><th>Type</th><th>Posted</th><th>Applicants</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="j in jobs" :key="j.id"><td><b>{{j.title}}</b><div class="muted">{{j.location}}</div></td><td>{{j.job_type}}</td><td>{{new Date(j.created_at).toLocaleDateString('en-ZA')}}</td><td><RouterLink :to="`/applicants?job=${j.id}`">View applicants →</RouterLink></td><td><span class="badge" :class="j.status==='active'?'green':'gold'">{{j.status}}</span></td><td><button class="btn btn-outline small" @click="setStatus(j,j.status==='active'?'paused':'active')">{{j.status==='active'?'Pause':'Activate'}}</button> <button class="btn btn-danger small" @click="remove(j)">Delete</button></td></tr></tbody></table></div><div v-else class="empty">You haven't posted a job yet.<p><RouterLink to="/post-job" class="btn btn-primary">Create your first job</RouterLink></p></div></template></AppShell></template>
<style scoped>.page-heading{display:flex;justify-content:space-between;align-items:end;gap:15px}.small{padding:7px 10px;font-size:11px}@media(max-width:650px){.page-heading{align-items:start;flex-direction:column}}</style>
